/// Newest first; the first entry is the default.
pub static SUPPORTED: [&Ids; 4] = [&V777, &V776, &V775, &V774];

pub fn for_protocol(protocol: i32) -> Option<&'static Ids> {
    SUPPORTED.iter().copied().find(|ids| ids.protocol == protocol)
}

/// "777 (26.3), 776 (26.2), ..." for messages.
pub fn supported_list() -> String {
    SUPPORTED
        .iter()
        .map(|ids| format!("{} ({})", ids.protocol, ids.name))
        .collect::<Vec<_>>()
        .join(", ")
}
